previewCss:
.darma-loader-darma-b8-pacman-chase { --accent: var(--loader-color, #facc15); --accent-2: var(--loader-secondary-color, #f8fafc); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .44); position: relative; display: flex; align-items: center; }
.darma-loader-darma-b8-pacman-chase .darma-loader-darma-b8-pacman-chase__head { position: relative; width: calc(var(--loader-size, 96px) * .44); height: calc(var(--loader-size, 96px) * .44); flex: none; }
.darma-loader-darma-b8-pacman-chase .darma-loader-darma-b8-pacman-chase__head::before, .darma-loader-darma-b8-pacman-chase .darma-loader-darma-b8-pacman-chase__head::after { content: ''; position: absolute; left: 0; width: 100%; height: 50%; background: var(--accent); }
.darma-loader-darma-b8-pacman-chase .darma-loader-darma-b8-pacman-chase__head::before { top: 0; border-radius: 100% 100% 0 0 / 200% 200% 0 0; transform-origin: 50% 100%; animation: darma-loader-darma-b8-pacman-chase-jaw-top calc(var(--loader-speed, 1s) * .5) ease-in-out infinite; }
.darma-loader-darma-b8-pacman-chase .darma-loader-darma-b8-pacman-chase__head::after { bottom: 0; border-radius: 0 0 100% 100% / 0 0 200% 200%; transform-origin: 50% 0%; animation: darma-loader-darma-b8-pacman-chase-jaw-bottom calc(var(--loader-speed, 1s) * .5) ease-in-out infinite; }
.darma-loader-darma-b8-pacman-chase span { width: calc(var(--loader-size, 96px) * .1); height: calc(var(--loader-size, 96px) * .1); margin-left: calc(var(--loader-size, 96px) * .13); border-radius: 50%; background: var(--accent-2); animation: darma-loader-darma-b8-pacman-chase-eat calc(var(--loader-speed, 1s) * 1.5) linear infinite; }
.darma-loader-darma-b8-pacman-chase span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .5); }
.darma-loader-darma-b8-pacman-chase span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * 1); }
@keyframes darma-loader-darma-b8-pacman-chase-jaw-top { 0%, 100% { transform: rotate(-38deg); } 50% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b8-pacman-chase-jaw-bottom { 0%, 100% { transform: rotate(38deg); } 50% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b8-pacman-chase-eat { 0% { transform: translateX(0); opacity: 1; } 100% { transform: translateX(calc(var(--loader-size, 96px) * -.2)); opacity: 0; } }

